def solve(expr):
    def precedence(op):
        if op == '+' or op == '-':
            return 1
        elif op == '*' or op == '/':
            return 2
        return 0

    def apply_op(values, ops):
        op = ops.pop()
        v = values.pop()
        if op == '+':
            values[-1] += v
        elif op == '-':
            values[-1] -= v
        elif op == '*':
            values[-1] *= v
        elif op == '/':
            values[-1] = values[-1] // v

    values = []
    ops = []
    i = 0
