                i += 1
            values.append(num)
            i -= 1  # Correcting the index since the for loop increments it once more
        elif expr[i] == '(':
            ops.append(expr[i])
        elif expr[i] == ')':
            while ops and ops[-1] != '(':
                apply_op(values, ops)
            ops.pop()  # Pop the '('
        elif expr[i] in '+-*/':
            while ops and precedence(ops[-1]) >= precedence(expr[i]):
                apply_op(values, ops)
            ops.append(expr[i])
        i += 1

    while ops:
        apply_op(values, ops)

    return values[0]

