import re

def parse_duration(s):
    if not s:
        raise ValueError("Empty string")

    pattern = re.compile(r'^(\d+d)?(\d+h)?(\d+m)?(\d+s)?$')
    match = pattern.match(s)

    if not match:
        raise ValueError("Unknown units or units out of order")

    days, hours, minutes, seconds = match.groups()

    units = {'d': 0, 'h': 0, 'm': 0, 's': 0}

    for unit in units:
        if getattr(match, unit) is not None:
            value = int(getattr(match, unit)[:-1])
            units[unit] = value

    for unit in units:
        if units[unit] == 0 and s.count(unit) > 0:
            raise ValueError(f"Unit {unit} without a number")

    for unit in units:
        if s.count(unit) > 1:
            raise ValueError(f"Repeated units {unit}")

    total_seconds = (units['d'] * 86400) + (units['h'] * 3600) + (units['m'] * 60) + units['s']

    return total_seconds

# Example usage:
