import re

def parse_duration(s):
    if not s:
        raise ValueError("Empty string is not allowed")

    pattern = re.compile(r'^(\d+d)?(\d+h)?(\d+m)?(\d+s)?$')
    match = pattern.match(s)

    if not match:
        raise ValueError("Unknown units or units out of order")

    days, hours, minutes, seconds = match.groups()

    if not any(days):
        days = 0
    else:
        days = int(days[:-1])

    if not any(hours):
        hours = 0
    else:
        hours = int(hours[:-1])

    if not any(minutes):
        minutes = 0
    else:
        minutes = int(minutes[:-1])

    if not any(seconds):
        seconds = 0
    else:
        seconds = int(seconds[:-1])

    if days < 0 or hours < 0 or minutes < 0 or seconds < 0:
        raise ValueError("Negative values are not allowed for time units")

    total_seconds = days * 86400 + hours * 3600 + minutes * 60 + seconds

    return total_seconds

# Example usage:
# print(parse_duration('1h30m'))  # Output: 5400
# print(parse_duration('45s'))    # Output: 45
# print(parse_duration('2h5s'))   # Output: 7205
# print(parse_duration('1d2h'))   # Output: 93600
```

