def shortest(graph, start, goal):
    if start == goal:
        return (0, [start])

    import heapq
    queue = [(0, start, [start])]
    visited = set()

    while queue:
        (cost, node, path) = heapq.heappop(queue)
        if node in visited:
            continue
        visited.add(node)

        if node == goal:
            return (cost, path)

        for neighbor, edge_cost in graph[node]:
            if neighbor not in visited:
                new_path = path + [neighbor]
                heapq.heappush(queue, (cost + edge_cost, neighbor, new_path))

    return (None, [])
```

