def shortest(graph, start, goal):
    import heapq
    if start == goal:
        return (0, [start])
    queue = [(0, start, [])]
    visited = set()
    while queue:
        (cost, v, path) = heapq.heappop(queue)
        if v not in visited:
            visited.add(v)
            path = path + [v]
            if v == goal:
                return (cost, path)
            for (neighbor, weight) in graph.get(v, []):
                if neighbor not in visited:
                    heapq.heappush(queue, (cost + weight, neighbor, path))
    return (None, [])
